'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var isPow2 = require( '@stdlib/math/base/assert/uint32-is-pow2' );
var format = require( '@stdlib/string/format' );
var accessors = require( './accessors.js' );


// MAIN //

/**
* Generates a Hadamard matrix using alternative indexing semantics.
*
* @param {NonNegativeInteger} N - number of rows and columns of the output matrix
* @param {Collection} out - output array
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @throws {RangeError} first argument must be a power of two
* @returns {Collection} output matrix
*
* @example
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* ghadamard( 2, out, 2, 1, 0 );
* // out => [ 1.0, 1.0, 1.0, -1.0 ]
*/
function ghadamard( N, out, strideOut1, strideOut2, offsetOut ) {
	var so1;
	var so2;
	var oo;
	var io;
	var ij;
	var d1;
	var d2;
	var d3;
	var v;
	var n;
	var i;
	var j;

	if ( N <= 0 ) {
		return out;
	}
	if ( !isPow2( N ) ) {
		throw new RangeError( format( 'invalid argument. First argument must be a power of two. Value: `%d`.', N ) );
	}
	// A Hadamard matrix is symmetric, so we can choose a loop order which iterates over the dimension having the smallest stride in the inner loop, thus ensuring cache optimal traversal...
	if ( isRowMajor( [ strideOut1, strideOut2 ] ) ) {
		so1 = strideOut1;
		so2 = strideOut2;
	} else {
		so1 = strideOut2;
		so2 = strideOut1;
	}
	oo = arraylike2object( out );
	if ( oo.accessorProtocol ) {
		accessors( N, oo, so1, so2, offsetOut );
		return out;
	}
	// Seed the top-left quadrant with the 1x1 Hadamard matrix:
	out[ offsetOut ] = 1.0;

	// Perform iterative doubling, copying the current n-by-n leading submatrix to the three remaining quadrants of the 2n-by-2n leading submatrix, with the bottom-right quadrant having flipped signs...
	for ( n = 1; n < N; n *= 2 ) {
		d1 = n * so1;
		d2 = n * so2;
		d3 = d1 + d2;
		io = offsetOut;
		for ( i = 0; i < n; i++ ) {
			ij = io;
			for ( j = 0; j < n; j++ ) {
				v = out[ ij ];
				out[ ij+d2 ] = v;
				out[ ij+d1 ] = v;
				out[ ij+d3 ] = -v;
				ij += so2;
			}
			io += so1;
		}
	}
	return out;
}


// EXPORTS //

module.exports = ghadamard;
